CREATE POLICY site_audio_select_public ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'site-audio');
CREATE POLICY site_audio_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'site-audio' AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY site_audio_admin_update ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'site-audio' AND public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (bucket_id = 'site-audio' AND public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY site_audio_admin_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'site-audio' AND public.has_role(auth.uid(), 'admin'::public.app_role));